76	// Ask one binary to describe itself: try `<bin> --describe`, else read the
77	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
78	// a human-readable note in `warn`.
79	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
80	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
81	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
82	    json::Parsed p = json::parse(r.out);
83	    if (p.ok) {
84	      std::string err = descriptor_from_json(p.value, d);
85	      if (err.empty()) {
86	        d.bin_path = bin.string();
87	        d.source = "--describe";
88	        return true;
89	      }
90	      warn = bin.string() + ": --describe JSON invalid: " + err;
91	    } else {
92	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
93	    }
94	  }
95	
96	  fs::path sidecar = bin;
97	  sidecar += ".json";
98	  std::error_code ec;
99	  if (fs::exists(sidecar, ec)) {
100	    json::Parsed p = json::parse(read_file(sidecar));
101	    if (p.ok) {
102	      EngineDescriptor sd;
103	      std::string err = descriptor_from_json(p.value, sd);
104	      if (err.empty()) {
105	        sd.bin_path = bin.string();
106	        sd.source = "sidecar";
107	        d = std::move(sd);
108	        return true;
109	      }
110	      warn = sidecar.string() + ": invalid descriptor: " + err;
111	    } else {
112	      warn = sidecar.string() + ": not JSON: " + p.error;
113	    }
114	  }
115	
116	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
117	  return false;
118	}
